const UI_KEY='lifeSim_ui';
function loadUI(){try{return Object.assign({subTab:{},logOpen:false,theme:'light'},JSON.parse(localStorage.getItem(UI_KEY)||'{}'))}catch(e){return {subTab:{},logOpen:false,theme:'light'}}}
