function electionHtml(){const live=(S.elections||[]).filter(e=>e.status==='Campaign');const cards=live.map(el=>{if(el.schemaVersion!==SCHOOL_ELECTION_SCHEMA_4B2)return `<div class="session-card is-live"><div class="session-head"><div><b>🗳️ ${esc(el.position||el.name||'Election')}</b><small>Election ${formatDate(el.date)}</small></div></div></div>`;const d=daysBetween(currentDate(),el.date),cand=el.candidates.map(c=>`<div><b>${esc(c.name)}</b><small>${esc(electionPublicStanding4B2(c.id))}</small>${el.playerCandidacy!=='Running'&&c.id!=='player'?`<button class="small ghost" data-school-election-support="${el.id}" data-candidate-id="${c.id}">${el.supportedCandidateId===c.id?'Supporting':'Support'}</button>`:''}</div>`).join('');return `<div class="session-card is-live"><div class="session-head"><div><b>🗳️ ${esc(el.position)} • ${esc(schoolDisplayName(el.schoolId))}${el.classId?` • ${esc(el.grade)} ${esc(el.classId)}`:''}</b><small>Election ${d<=0?'today':`in ${d} day${d===1?'':'s'}`} • ${esc(el.playerCandidacy)}</small></div></div><div class="candidate-grid">${cand}</div>${el.playerCandidacy==='Running'?`<div class="session-actions">${Object.entries(CAMPAIGN).filter(([,c])=>S.age>=(c.minAge||0)).map(([k,c])=>`<button class="small ${el.done?.[`${k}-${currentDate()}`]?'ghost':''}" data-campaign="${el.id}" data-kind="${k}" ${el.done?.[`${k}-${currentDate()}`]?'disabled':''}>${esc(c.label)}</button>`).join('')}</div><small class="muted-text">Campaign actions: ${(el.campaignLog||[]).length}/10${el.promise?` • Promise: ${esc(el.promise)}`:''}</small>`:''}</div>`}).join('');const recent=(S.elections||[]).filter(e=>e.schemaVersion===SCHOOL_ELECTION_SCHEMA_4B2&&e.status==='Decided').slice(0,3).map(el=>`<div class="timeline-entry"><span>${esc(el.position)} • ${formatDate(el.date)}</span><b>${esc(el.winner||'Winner')} elected</b><p>${(el.results||[]).map(x=>`${esc(x.name)} ${x.votes} (${x.share}%)`).join(' • ')}${el.tieResolved?' • Tie resolved by teacher tie-break.':''}</p></div>`).join('');return schoolElectionEntryHtml4B2()+cards+(recent?`<h4>Recent election results</h4>${recent}`:'')}
function schoolElectionClick4B2(b){const d=b.dataset;if(d.schoolElectionRun){const r=beginSchoolElection4B2({kind:d.schoolElectionRun,roleId:d.schoolElectionRole,playerMode:'running'});if(!r.ok)toast(r.detail||r.reason);save();render();return true}if(d.schoolElectionFollow){const r=beginSchoolElection4B2({kind:d.schoolElectionFollow,roleId:d.schoolElectionRole,playerMode:'declined'});if(!r.ok)toast(r.detail||r.reason);save();render();return true}if(d.schoolElectionSupport){const r=supportCandidate4B2(d.schoolElectionSupport,d.candidateId);if(!r.ok)toast(r.reason);save();render();return true}return false}
// =====================================================================
// PHASE 4B.3 — CLUB / TEAM LEADERSHIP + UNIQUE ROLE INTEGRITY
