const CLUB_LEADERSHIP_SCHEMA_4B3=1;
const LEADERSHIP_METHOD_LABELS_4B3={member_vote:'member vote',advisor_appointment:'advisor appointment',coach_selection:'coach selection',coach_and_team_selection:'coach + team assessment',director_appointment:'director appointment',audition:'audition / director selection'};
function leadershipState4B3(){const st=schoolOrganizationState4B1();st.leadershipSchemaVersion=CLUB_LEADERSHIP_SCHEMA_4B3;st.leadershipSelections=Array.isArray(st.leadershipSelections)?st.leadershipSelections:[];return st}
function clubForOrganization4B3(orgId){const sid=playerCurrentSchoolId4A2();return (S.school?.clubs||[]).find(c=>{if(!c?.name)return false;const type=organizationTypeForClub4B1(c.name);return organizationId4B1(c.schoolId4B1||sid,type,c.name)===orgId})||null}
function clubOrganization4B3(c){if(!c||!S.school)return null;const sid=c.schoolId4B1||playerCurrentSchoolId4A2();if(!sid||!schoolById(sid)||sid!==playerCurrentSchoolId4A2())return null;c.schoolId4B1=sid;const type=organizationTypeForClub4B1(c.name);if(type==='student_council')return null;const org=ensureOrganization4B1({schoolId:sid,name:c.name,type,memberIds:c.status==='Active'?['player']:[],roles:standardRoleDefinitions4B1(type,c.name)});if(org&&c.status==='Active'&&!org.memberIds.includes('player'))org.memberIds.push('player');return org}
function syncClubOrganization4B3(c){const org=clubOrganization4B3(c);if(!org)return null;configureLeadershipRoles4B3(c,org);ensureLeadershipNpcMembers4B3(c,org,5);seedLeadershipIncumbent4B3(c,org);syncLegacyClubLeadership4B3(c,org);return org}
function leadershipRoleSequence4B3(c){const ladder=clubInfo(c?.name).ladder;return ladder==='sport'?[{position:'Vice Captain',roleId:'vice_captain'},{position:'Captain',roleId:'captain'}]:ladder==='debate'?[{position:'Vice Captain',roleId:'vice_captain'},{position:'Captain',roleId:'captain'}]:ladder==='drama'?[{position:'Stage manager',roleId:'stage_manager'},{position:'Club President',roleId:'president'}]:ladder==='newspaper'?[{position:'Editor-in-Chief',roleId:'editor_in_chief'}]:ladder==='music'?[{position:'Section leader',roleId:'section_leader'},{position:'Concertmaster',roleId:'concertmaster'},{position:'Ensemble President',roleId:'president'}]:[{position:'Vice President',roleId:'vice_president'},{position:'President',roleId:'president'}]}
function leadershipPositionForRole4B3(c,roleId){return leadershipRoleSequence4B3(c).find(x=>x.roleId===roleId4B1(roleId))?.position||roleDisplay4B1(roleId4B1(roleId))}
function primaryLeadershipRole4B3(c){const seq=leadershipRoleSequence4B3(c);return seq[seq.length-1]||null}
function selectionMethod4B3(c,roleId){const rid=roleId4B1(roleId),ladder=clubInfo(c?.name).ladder;if(ladder==='sport')return 'coach_selection';if(ladder==='debate')return rid==='captain'?'coach_and_team_selection':'coach_selection';if(ladder==='newspaper')return 'advisor_appointment';if(ladder==='drama')return rid==='stage_manager'?'director_appointment':'member_vote';if(ladder==='music')return rid==='concertmaster'?'audition':rid==='section_leader'?'director_appointment':'member_vote';return 'member_vote'}
function configureLeadershipRoles4B3(c,org){if(!c||!org)return;for(const x of leadershipRoleSequence4B3(c)){let role=roleDefinition4B1(org,x.roleId);if(!role)role=addRoleDefinition4B1(org,{roleId:x.roleId,displayName:x.position,unique:x.roleId!=='section_leader'});role.displayName=x.position;role.selectionMethod=selectionMethod4B3(c,x.roleId);role.eligibility=Object.assign({},role.eligibility||{},{membershipRequired:true,schoolId:org.schoolId})}}
function npcLeadershipFit4B3(n,c,method){if(!n)return 0;const tr=n.traits||[],go=n.goals||[];let x=28+(n.reputation||30)*.42+(n.interest===c.name?12:0)+(tr.includes('Ambitious')?8:0)+(tr.includes('Responsible')?6:0)+(tr.includes('Outgoing')?4:0)+(tr.includes('Competitive')?4:0)+(go.includes('classPresident')?4:0);if(/coach/.test(method))x+=(tr.includes('Athletic')?10:0)+(n.interest===c.name?6:0);if(method==='advisor_appointment'||method==='director_appointment')x+=(tr.includes('Studious')?5:0)+(tr.includes('Creative')?5:0);return clamp(x+(hashOf(`${n.id}|${c.name}|${method}`)%1400)/100-7,12,96)}
function ensureLeadershipNpcMembers4B3(c,org,min=5){if(!c||!org)return [];let pool=(S.npcs||[]).filter(n=>{syncNpcSchool4A3(n);return n.currentSchoolId===org.schoolId&&Math.abs(npcAge(n)-S.age)<=2});let guard=0;while(pool.length<min&&guard++<12){const n=generateHousehold({kids:1,childAge:S.age,schoolId:org.schoolId,schoolGrade:S.school?.grade,schoolClass:S.school?.className})[0];if(n&&!n.interest)n.interest=c.name;pool=(S.npcs||[]).filter(x=>{syncNpcSchool4A3(x);return x.currentSchoolId===org.schoolId&&Math.abs(npcAge(x)-S.age)<=2})}const preferred=[...pool].sort((a,b)=>{const ai=a.interest===c.name?1:0,bi=b.interest===c.name?1:0;if(bi!==ai)return bi-ai;const ds=(b.reputation||0)-(a.reputation||0);return ds||String(a.id).localeCompare(String(b.id))}).slice(0,Math.max(min,5));org.memberIds=[...new Set([...(org.memberIds||[]),...preferred.map(n=>n.id),...(c.status==='Active'?['player']:[])])];c.memberIds4B3=preferred.map(n=>n.id);c.members=[...new Set([...(c.members||[]),...preferred.slice(0,4).map(n=>n.fullName)])].slice(0,8);return preferred}
function topIncumbent4B3(c,org){const top=primaryLeadershipRole4B3(c);return top?roleDefinition4B1(org,top.roleId)?.holders?.[0]?.holderId||null:null}
function seedLeadershipIncumbent4B3(c,org){if(!c||!org||c.leadershipSeeded4B3)return null;configureLeadershipRoles4B3(c,org);const top=primaryLeadershipRole4B3(c),role=top&&roleDefinition4B1(org,top.roleId);if(!top||!role){c.leadershipSeeded4B3=true;return null}if(role.holders?.length){c.leadershipSeeded4B3=true;return role.holders[0].holderId}const npcs=ensureLeadershipNpcMembers4B3(c,org,5),method=selectionMethod4B3(c,top.roleId),best=[...npcs].sort((a,b)=>npcLeadershipFit4B3(b,c,method)-npcLeadershipFit4B3(a,c,method)||String(a.id).localeCompare(String(b.id)))[0];if(best){assignSchoolRole4B1(org.organizationId,top.roleId,best.id,{source:'4B.3 initial incumbent',requireMembership:true});c.leaderNpc=best.fullName}c.leadershipSeeded4B3=true;return best?.id||null}
function playerLeadershipEligibility4B3(c,org,roleId){if(!c||c.status!=='Active'||!org)return {ok:false,reason:'You are not an active member of this organization.'};if(org.schoolId!==playerCurrentSchoolId4A2())return {ok:false,reason:'This organization belongs to another school.'};if(!(org.memberIds||[]).includes('player'))return {ok:false,reason:'You must be a member before becoming a leader.'};const rid=roleId4B1(roleId),role=roleDefinition4B1(org,rid);if(!role)return {ok:false,reason:'That role is not available here.'};if(role.holders?.some(h=>h.holderId==='player'))return {ok:false,reason:`You already hold ${role.displayName}.`};const seq=leadershipRoleSequence4B3(c),target=seq.findIndex(x=>x.roleId===rid),L=ladderFor(c),cur=L.indexOf(c.position),needPos=target>0?L.indexOf(seq[target-1].position):Math.max(0,L.length-seq.length-1);if(cur<needPos){const needLabel=target>0?seq[target-1].position:(L[needPos]||'an experienced member');return {ok:false,reason:`Build experience as ${needLabel} before seeking ${role.displayName}.`}};const sport=organizationTypeForClub4B1(c.name)==='sports_team',minAttend=sport?8:6,minSkill=sport?45:35;if((c.attended||0)<minAttend)return {ok:false,reason:`Attend at least ${minAttend} sessions first.`};if(clubAttendanceRate(c)<65)return {ok:false,reason:'Your attendance needs to be at least 65%.'};if((c.skill||0)<minSkill)return {ok:false,reason:`Your ${c.name} skill needs to be at least ${minSkill}%.`};if((c.leaderRel||50)<45)return {ok:false,reason:`Improve your standing with ${c.leader||'the advisor'} first.`};return {ok:true,reason:'Eligible'}}
function playerLeadershipScore4B3(c,method){const r=ensureRep(),attendance=clubAttendanceRate(c),base=(c.skill||0)*.38+(c.leaderRel||50)*.2+attendance*.12+(r.leadership||0)*.2+(r.club||0)*.1;let extra=0;if(/coach/.test(method))extra=skillValue('fitness')*.08+skillValue('sports')*.08+(S.health||50)*.03;if(method==='member_vote')extra=(r.social||0)*.08+(r.kindness||0)*.04;if(method==='advisor_appointment'||method==='director_appointment')extra=(r.academic||0)*.06+(S.smart||50)*.04;if(method==='audition')extra=skillValue('music')*.12;return clamp(base+extra+(hashOf(`${S.name}|${c.name}|${method}|player`)%600)/100-3,10,99)}
function publicLeadershipStanding4B3(id,c){if(id==='player')return 'You';const n=npcById(id),p=(S.people||[]).find(x=>x.npcId===id);if(!n)return 'Member';const rel=p?(p.rel>=70?'close to you':p.rel>=50?'friendly with you':p.rel<=25?'tense with you':'known to you'):'not personally known';return `${rel} • ${n.interest===c.name?'committed member':'organization member'}`}
function selectionDate4B3(){let d=nextSchoolDay(addDays(currentDate(),3));for(let i=0;i<12;i++){const hit=(S.calendar||[]).some(e=>e.dateISO===d&&!isTerminal(e.status)&&(e.startMinute??0)<1020&&(e.endMinute??1440)>930);if(!hit)return d;d=nextSchoolDay(addDays(d,1))}return d}
function leadershipSelectionKey4B3(orgId,roleId,vacancyDate){return `${orgId}|${roleId4B1(roleId)}|${vacancyDate||currentDate()}`}
function activeLeadershipSelection4B3(orgId,roleId){return leadershipState4B3().leadershipSelections.find(x=>x.organizationId===orgId&&x.roleId===roleId4B1(roleId)&&['Scheduled','Due'].includes(x.status))||null}
function openLeadershipSelection4B3({clubId=null,organizationId=null,roleId=null,playerApplies=true,reason='vacancy'}={}){migrateClubLeadership4B3({seed:false});const c=clubId?clubById(clubId):clubForOrganization4B3(organizationId),org=organizationId?schoolOrganizationById4B1(organizationId):clubOrganization4B3(c);if(!c||!org)return {ok:false,reason:'missing-context'};configureLeadershipRoles4B3(c,org);const next=roleId?{roleId:roleId4B1(roleId),position:leadershipPositionForRole4B3(c,roleId)}:nextLeadershipRole4B3(c);if(!next)return {ok:false,reason:'no-next-role'};const role=roleDefinition4B1(org,next.roleId);if(role?.holders?.length)return {ok:false,reason:'occupied',holderId:role.holders[0].holderId};if(playerApplies){const elig=playerLeadershipEligibility4B3(c,org,next.roleId);if(!elig.ok)return {ok:false,reason:'ineligible',detail:elig.reason}}ensureLeadershipNpcMembers4B3(c,org,5);const vacancy=c.leadershipVacancies4B3?.[next.roleId]||currentDate(),key=leadershipSelectionKey4B3(org.organizationId,next.roleId,vacancy),existing=leadershipState4B3().leadershipSelections.find(x=>x.selectionKey===key);if(existing)return {ok:true,existing:true,selectionId:existing.id,status:existing.status};const method=selectionMethod4B3(c,next.roleId),npcIds=(org.memberIds||[]).filter(id=>id!=='player'&&npcById(id)).sort((a,b)=>npcLeadershipFit4B3(npcById(b),c,method)-npcLeadershipFit4B3(npcById(a),c,method)||String(a).localeCompare(String(b))).slice(0,3),candidates=npcIds.map(id=>({id,personId:id,name:npcById(id).fullName,publicStanding:publicLeadershipStanding4B3(id,c)}));if(playerApplies)candidates.push({id:'player',personId:'player',name:S.name,publicStanding:'You'});if(!candidates.length)return {ok:false,reason:'no-candidates'};const date=selectionDate4B3(),sel={id:uid('leadsel'),schemaVersion:CLUB_LEADERSHIP_SCHEMA_4B3,selectionKey:key,organizationId:org.organizationId,schoolId:org.schoolId,clubId:c.id,organizationName:org.name,roleId:next.roleId,roleName:role.displayName,method,reason,startDate:currentDate(),date,status:'Scheduled',playerApplied:!!playerApplies,candidates,resultLocked:false,winnerId:null,results:null};leadershipState4B3().leadershipSelections.unshift(sel);createCalendarEvent({id:`leadsel-${sel.id}`,type:'leadershipSelection',title:`${c.name} • ${role.displayName} selection`,dateISO:date,startMinute:930,endMinute:990,graceMinute:945,payload:{selectionId:sel.id},required:false,location:organizationTypeForClub4B1(c.name)==='sports_team'?'School gym / field':'School club room',source:'club'});log(`${role.displayName} selection`,`${c.name} will choose its next ${role.displayName} on ${formatDate(date)} by ${LEADERSHIP_METHOD_LABELS_4B3[method]||method}.${playerApplies?' You are a candidate.':''}`);return {ok:true,selectionId:sel.id,status:sel.status}}
function nextLeadershipRole4B3(c){const org=clubOrganization4B3(c);if(!org)return null;configureLeadershipRoles4B3(c,org);const seq=leadershipRoleSequence4B3(c),held=new Set(activeRolesForHolder4B1('player').filter(x=>x.organizationId===org.organizationId).map(x=>x.roleId));for(const x of seq){if(held.has(x.roleId))continue;const L=ladderFor(c),cur=L.indexOf(c.position),idx=L.indexOf(x.position);if(idx<0||idx>cur)return x}return null}
function selectionCandidateScore4B3(sel,id,c){if(id==='player')return playerLeadershipScore4B3(c,sel.method);return npcLeadershipFit4B3(npcById(id),c,sel.method)}
function resolveLeadershipSelection4B3(sel,{playerAttended=true,simulated=false}={}){if(!sel)return null;if(sel.resultLocked||sel.status==='Decided')return sel.results||null;const c=clubById(sel.clubId),org=schoolOrganizationById4B1(sel.organizationId),role=roleDefinition4B1(org,sel.roleId);if(!c||!org||!role){sel.status='Cancelled';sel.resultLocked=true;return null}if(role.holders?.length){sel.status='Cancelled';sel.resultLocked=true;sel.cancelReason='Role filled before selection';const ev=(S.calendar||[]).find(e=>e.id===`leadsel-${sel.id}`);if(ev)setCalendarStatus(ev,'Cancelled','Role already filled');return null}const candidates=(sel.candidates||[]).filter(x=>x.id!=='player'||playerAttended),rows=candidates.map(x=>({id:x.id,name:x.name,score:Math.round(selectionCandidateScore4B3(sel,x.id,c)*10)/10}));if(!rows.length){sel.status='Cancelled';sel.resultLocked=true;return null}rows.sort((a,b)=>b.score-a.score||String(a.id).localeCompare(String(b.id)));const top=rows[0].score,tied=rows.filter(x=>Math.abs(x.score-top)<0.001);const winner=tied.length>1?[...tied].sort((a,b)=>(hashOf(`${sel.selectionKey}|${a.id}|tie`)%10000)-(hashOf(`${sel.selectionKey}|${b.id}|tie`)%10000)||String(a.id).localeCompare(String(b.id)))[0]:rows[0];const assigned=assignSchoolRole4B1(org.organizationId,role.roleId,winner.id,{source:'4B.3 leadership selection',requireMembership:true});if(!assigned.ok){sel.status='Cancelled';sel.resultLocked=true;sel.cancelReason=assigned.reason;return null}sel.status='Decided';sel.resultLocked=true;sel.decidedDate=currentDate();sel.results=rows.map(x=>({id:x.id,name:x.name,outcome:x.id===winner.id?'Selected':'Not selected'}));sel.winnerId=winner.id;sel.winner=winner.name;sel.tieResolved=tied.length>1;delete c.leadershipVacancies4B3?.[role.roleId];syncLegacyClubLeadership4B3(c,org);const ev=(S.calendar||[]).find(e=>e.id===`leadsel-${sel.id}`);if(ev)setCalendarStatus(ev,'Completed',winner.id==='player'?'Player selected':'Leadership selected');recordOutcome('Club leadership',`${role.displayName} • ${c.name}`,winner.id==='player'?'Selected':`Selected: ${winner.name}`,`${LEADERSHIP_METHOD_LABELS_4B3[sel.method]||sel.method}. Candidates: ${rows.map(x=>x.name).join(', ')}.`);if(winner.id==='player'){addRep('leadership',10);addRep(clubInfo(c.name).rep,4);if(!simulated){setEmotion('Proud',`Selected as ${role.displayName}.`,70);log(`🏅 ${c.name}: ${role.displayName}`,`You are selected through ${LEADERSHIP_METHOD_LABELS_4B3[sel.method]||sel.method}.`,true)}}else if(sel.playerApplied&&!simulated){addRep('leadership',2);const p=(S.people||[]).find(x=>x.npcId===winner.id);if(p){rememberPerson(p,`${winner.name} was selected as ${role.displayName} in ${c.name}.`,2);p.rel=clamp(p.rel+(p.rel>=50?2:0))}log(`${c.name} leadership result`,`${winner.name} is selected as ${role.displayName}. You remain a member and can keep building experience.`)}return sel.results}
function resolveLeadershipSelectionById4B3(id,opts={}){return resolveLeadershipSelection4B3(leadershipState4B3().leadershipSelections.find(x=>x.id===id),opts||{})}
function attendLeadershipSelection4B3(id){const sel=leadershipState4B3().leadershipSelections.find(x=>x.id===id);if(!sel||!['Scheduled','Due'].includes(sel.status))return false;const ev=(S.calendar||[]).find(e=>e.id===`leadsel-${sel.id}`);if(!ev)return false;if(ev.dateISO!==currentDate()){toast(`The selection is on ${formatDate(ev.dateISO)}.`);return false}if(currentMinute()>ev.graceMinute){processCalendar();return false}if(currentMinute()<ev.startMinute){if(ev.startMinute-currentMinute()>180){toast(`Selection begins at ${timeLabel(ev.startMinute)}.`);return false}advanceTime(ev.startMinute-currentMinute(),{silent:true})}setCalendarStatus(ev,'Attending','Checked in');advanceTime(Math.max(30,ev.endMinute-currentMinute()),{silent:true});resolveLeadershipSelection4B3(sel,{playerAttended:true});return true}
function leadershipSelectionDue4B3(ev){const sel=leadershipState4B3().leadershipSelections.find(x=>x.id===ev.payload?.selectionId);if(!sel||sel.resultLocked){setCalendarStatus(ev,'Cancelled','Selection unavailable');return}sel.status='Due';notify(`${sel.roleName} selection now`,`${sel.organizationName} • ${timeLabel(ev.startMinute)}.`,{sourceType:'calendar',sourceId:ev.id,tab:'school'});offerContext(calendarContext(ev))}
function leadershipSelectionMissed4B3(ev){const sel=leadershipState4B3().leadershipSelections.find(x=>x.id===ev.payload?.selectionId);if(sel&&!sel.resultLocked)resolveLeadershipSelection4B3(sel,{playerAttended:false});if(!isTerminal(ev.status))setCalendarStatus(ev,'Completed','Selection resolved without Player attendance')}
function simulateLeadershipSelection4B3(ev){const sel=leadershipState4B3().leadershipSelections.find(x=>x.id===ev.payload?.selectionId);if(!sel||sel.resultLocked){setCalendarStatus(ev,'Cancelled','Selection unavailable');return}const attended=!sel.playerApplied||chance(attendTendency('leadershipSelection'));resolveLeadershipSelection4B3(sel,{playerAttended:attended,simulated:true});if(!isTerminal(ev.status))setCalendarStatus(ev,'Completed','Simulated leadership selection')}
