 if(!['sale','tip','expense','refund','replacement'].includes(kind)||!Number.isFinite(amount)||(kind==='replacement'?amount!==0:amount<=0)||Math.round(amount*100)/100!==amount)return {ok:false,reason:'invalid_transaction'};
