 if(observed?.known&&observed.schoolId===n.currentSchoolId||inquiry?.schoolId===n.currentSchoolId)
  return {known:true,schoolId:n.currentSchoolId,source:inquiry?.schoolId===n.currentSchoolId?'asked':'school_provenance'};
